static uint16_t handle_th_filament_cmd(const uint8_t *frame, uint16_t plen, uint8_t *out_buf)
{
    const uint8_t src_id = frame[2];
    const uint8_t cmd_id = frame[5];
    const uint16_t seq = (uint16_t)frame[8] | ((uint16_t)frame[9] << 8U);
    if (plen < (uint16_t)sizeof(minimc_filament_req_t))
    {
        return build_nack_resp(src_id, seq, 0x02U, out_buf);
    }
    const uint8_t slot_id = frame[12];
    const uint8_t action = frame[13];
    const int16_t len_mm = (int16_t)((uint16_t)frame[14] | ((uint16_t)frame[15] << 8U));
    if ((slot_id >= 4U) || (action > 3U))
    {
        return build_nack_resp(src_id, seq, 0x03U, out_buf);
    }
    const char *op_str = apply_th_filament_action(cmd_id, slot_id, action, len_mm);
    const uint8_t present_mask = (Board_getFilamentStatus() == 0U) ? 0x0FU : 0x00U;
    th_debug_notify_filament(op_str, slot_id, present_mask, "DONE");

    init_th_resp_hdr(out_buf, src_id, MINIMC_CMD_SLOT_SELECT, seq);
    out_buf[12] = slot_id;
    out_buf[13] = present_mask;
    out_buf[14] = (action == 2U) ? 2U : ((action == 1U) ? 1U : 0U);
    out_buf[15] = 0U;
    return finalize_th_resp_frame(out_buf, 4U);
}

/**
 * @brief 处理 0x17 (MOTION_STOP) 紧急停止指令并返回 0x00 ACK 帧。
 */
static uint16_t handle_th_motion_stop(const uint8_t *frame, uint16_t plen, uint8_t *out_buf)
{
    const uint8_t src_id = frame[2];
    const uint16_t seq = (uint16_t)frame[8] | ((uint16_t)frame[9] << 8U);
    if (plen > 1U)
    {
        return build_nack_resp(src_id, seq, 0x02U, out_buf);
    }
    quickStop();
    thermistor_set_target_deci_c(0);
    load_filament_Flag = 0;
    (void)th_control_enqueue_gcode("M112", 4U, true);
    init_th_resp_hdr(out_buf, src_id, MINIMC_CMD_ACK, seq);
    return finalize_th_resp_frame(out_buf, 0U);
}

/**
 * @brief 解析 0x1C 级联 G-code 关键副作用（M104/M109 设温、T0~T3 选槽、M112 急停）。
 */
static void th_apply_gcode_side_effects(const char *gcode)
{
    if ((strncmp(gcode, "M104", 4) == 0) || (strncmp(gcode, "M109", 4) == 0))
    {
        const char *s_ptr = strchr(gcode, 'S');
        if (s_ptr != NULL)
        {
            const int temp_c = atoi(s_ptr + 1);
            if ((temp_c >= 0) && (temp_c <= 300))
            {
                thermistor_set_target_deci_c((int16_t)(temp_c * 10));
            }
        }
    }
    else if ((gcode[0] == 'T') && (gcode[1] >= '0') && (gcode[1] <= '3'))
    {
        const uint8_t slot = (uint8_t)(gcode[1] - '0');
        const uint8_t mask = (Board_getFilamentStatus() == 0U) ? 0x0FU : 0x00U;
        load_filament_Flag = 0;
        th_debug_notify_filament("SELECT", slot, mask, "DONE");
    }
    else if (strncmp(gcode, "M112", 4) == 0)
    {
        quickStop();
        thermistor_set_target_deci_c(0);
    }
}

/**
 * @brief 处理 0x1C (GCODE_EXEC) 级联 G-code 执行指令并返回 4B 队列状态响应帧。
 */
static uint16_t handle_th_gcode_exec(const uint8_t *frame, uint16_t plen, uint8_t *out_buf)
{
    const uint8_t src_id = frame[2];
    const uint16_t seq = (uint16_t)frame[8] | ((uint16_t)frame[9] << 8U);
    if (plen < 2U)
    {
        return build_nack_resp(src_id, seq, 0x02U, out_buf);
    }
    const uint8_t line_len = frame[12];
    const uint8_t exec_flags = frame[13];
    if ((line_len == 0U) || (line_len > 46U) || ((uint16_t)(2U + line_len) > plen))
    {
        return build_nack_resp(src_id, seq, 0x02U, out_buf);
    }
    char gcode_line[48];
    memcpy(gcode_line, &frame[14], line_len);
    gcode_line[line_len] = '\0';
    const bool ok = th_control_enqueue_gcode(gcode_line, line_len, (exec_flags & 0x01U) != 0U);
    if (ok)
    {
        th_apply_gcode_side_effects(gcode_line);
    }

    init_th_resp_hdr(out_buf, src_id, MINIMC_CMD_GCODE_EXEC, seq);
    out_buf[12] = ok ? 0U : 1U;
    out_buf[13] = th_control_get_queue_free();
    out_buf[14] = (uint8_t)(seq & 0xFFU);
    out_buf[15] = (uint8_t)((seq >> 8U) & 0xFFU);
    return finalize_th_resp_frame(out_buf, 4U);
}

/**
 * @brief 分发 TH 命令码并构造响应报文。
 */
static uint16_t dispatch_th_command(const uint8_t *frame, uint16_t plen, uint8_t *out_buf)
{
    const uint8_t src_id = frame[2];
    const uint8_t cmd_id = frame[5];
    const uint16_t seq = (uint16_t)frame[8] | ((uint16_t)frame[9] << 8U);
    if (cmd_id == MINIMC_CMD_GET_VERSION)
    {
        return build_version_resp(src_id, seq, out_buf);
    }
    if (cmd_id == MINIMC_CMD_PING)
    {
        return build_pong_resp(src_id, seq, &frame[MINIMC_HEADER_SIZE], out_buf);
    }
    if (cmd_id == MINIMC_CMD_GET_TEMP)
    {
        return build_temp_resp_with_cmd(src_id, seq, MINIMC_CMD_TEMP_REPORT, out_buf);
    }
    if (cmd_id == MINIMC_CMD_SET_TEMP)
    {
        return handle_th_set_temp(frame, plen, out_buf);
    }
    if ((cmd_id == MINIMC_CMD_FILAMENT_CONTROL) ||
        (cmd_id == MINIMC_CMD_SLOT_SELECT) ||
        (cmd_id == MINIMC_CMD_FILAMENT_LEGACY))
    {
        return handle_th_filament_cmd(frame, plen, out_buf);
    }
    if (cmd_id == MINIMC_CMD_MOTION_STOP)
    {
        return handle_th_motion_stop(frame, plen, out_buf);
    }
    if (cmd_id == MINIMC_CMD_GCODE_EXEC)
    {
        return handle_th_gcode_exec(frame, plen, out_buf);
    }
    return build_nack_resp(src_id, seq, 0x04U, out_buf);
}

