/**
 * @brief 触发热敏电阻安全锁死：关闭加热器目标温度与 PWM 输出
 */
void thermistor_safety_lock(void)
{
    /* 硬件安全不变量：故障态强制清零加热占空比与目标温度 */
    s_target_temp_deci_c = 0;
    target_temperature[0] = 0;
    soft_pwm[0] = 0;
    tmr_channel_value_set(TMR3, TMR_SELECT_CHANNEL_2, 0U);
}

/**
 * @brief 设置 TH 喷头目标温度（0.1℃）并同步写入 PID 温控数组
 * @param target_deci_c 目标温度（0.1℃）
 */
void thermistor_set_target_deci_c(int16_t target_deci_c)
{
    if (target_deci_c < 0)
    {
        return;
    }
    int16_t clamped = target_deci_c;
    if (clamped > 2500)
    {
        clamped = 2500;
    }
    s_target_temp_deci_c = clamped;
    target_temperature[0] = (int)(clamped / 10);
}

/**
 * @brief 获取当前 TH 喷头目标温度（0.1℃）
 * @return 当前目标温度（0.1℃）
 */
int16_t thermistor_get_target_deci_c(void)
{
    if ((s_target_temp_deci_c == 0) && (target_temperature[0] > 0))
    {
        return (int16_t)(target_temperature[0] * 10);
    }
    return s_target_temp_deci_c;
}

/**
 * @brief 初始化热敏电阻 ADC 外设与校准流程
 */
void thermistor_adcConfig(void)
{
    thermistor_safety_lock();
    adc_hw_init();
    adc_calibrate_with_timeout();
}

static bool adc_read_single_raw(adc_type *adc_x, uint16_t *out_val)
{
    if (adc_x == NULL || out_val == NULL)
    {
        return false;
    }
    adc_ordinary_software_trigger_enable(adc_x, TRUE);
    uint32_t timeout = ADC_POLL_TIMEOUT_CYCLES;
    while (!adc_flag_get(adc_x, ADC_OCCE_FLAG) && (timeout > 0U))
    {
        timeout--;
    }
    if (timeout == 0U)
    {
        return false;
    }
    adc_flag_clear(adc_x, ADC_OCCE_FLAG);
    *out_val = adc_ordinary_conversion_data_get(adc_x);
    return true;
}

uint16_t adc_single_conversion_get(adc_type *adc_x, adc_channel_select_type channel)
{
    if (adc_x == NULL)
    {
        return 0U;
    }
    adc_ordinary_channel_set(adc_x, channel, 1, ADC_SAMPLETIME_247_5);
    uint32_t sum = 0U;
    for (uint8_t i = 0U; i < 16U; i++)
    {
        uint16_t val = 0U;
        if (!adc_read_single_raw(adc_x, &val))
        {
            return 0U;
        }
        sum += val;
    }
    return (uint16_t)sum;
}

static bool sample_adc_average(uint16_t *out_avg)
{
    if (out_avg == NULL)
    {
        return false;
    }
    adc_ordinary_channel_set(ADC1, ADC_CHANNEL_5, 1, ADC_SAMPLETIME_247_5);
    uint32_t sum = 0U;
    const uint8_t sample_count = 16U;
    for (uint8_t i = 0U; i < sample_count; i++)
    {
        uint16_t val = 0U;
        if (!adc_read_single_raw(ADC1, &val))
        {
            return false;
        }
        sum += val;
    }
    *out_avg = (uint16_t)(sum / sample_count);
    return true;
}

static int16_t ntc_adc_to_deci_c(uint16_t adc)
{
    if (adc <= s_ntc_table[0].adc)
    {
        return s_ntc_table[0].temp_deci_c;
    }
    const uint8_t count = (uint8_t)(sizeof(s_ntc_table) / sizeof(s_ntc_table[0]));
    for (uint8_t i = 1U; i < count; i++)
    {
        if (adc <= s_ntc_table[i].adc)
        {
            const int32_t a0 = (int32_t)s_ntc_table[i - 1U].adc;
            const int32_t a1 = (int32_t)s_ntc_table[i].adc;
            const int32_t t0 = (int32_t)s_ntc_table[i - 1U].temp_deci_c;
            const int32_t t1 = (int32_t)s_ntc_table[i].temp_deci_c;
            const int32_t da = a1 - a0;
            if (da == 0)
            {
                return (int16_t)t0;
            }
            const int32_t interp = t0 + (((int32_t)adc - a0) * (t1 - t0)) / da;
            return (int16_t)interp;
        }
    }
    return s_ntc_table[count - 1U].temp_deci_c;
}

/**
 * @brief 采集 TH 喷头热敏电阻实时遥测数据，仅在传感器故障分支调用安全锁死
 * @param report 输出温度遥测载荷结构体指针
 * @return true 采集完成，false 入参为空指针
 */
bool thermistor_adc_get_telemetry(minimc_temp_report_payload_t *report)
{
    if (report == NULL)
    {
        return false;
    }

    report->sample_timestamp_ms = get_tick_count();
    report->reserved = 0U;

    uint16_t raw_adc = 0U;
    if (!sample_adc_average(&raw_adc))
    {
        thermistor_safety_lock();
        report->current_temp_deci_c = MINIMC_TEMP_FAULT_VALUE_DECI_C;
        report->target_temp_deci_c = 0;
        report->raw_adc_value = 0U;
        report->sensor_status = MINIMC_TEMP_STATUS_TIMEOUT;
        report->heater_duty_percent = 0U;
        return true;
    }

    if ((raw_adc > ADC_OPEN_CIRCUIT_THRESHOLD) || (raw_adc < ADC_SHORT_CIRCUIT_THRESHOLD))
    {
        const bool is_open = (raw_adc > ADC_OPEN_CIRCUIT_THRESHOLD);
        thermistor_safety_lock();
        report->current_temp_deci_c = MINIMC_TEMP_FAULT_VALUE_DECI_C;
        report->target_temp_deci_c = 0;
        report->raw_adc_value = is_open ? 4095U : 0U;
        report->sensor_status = is_open ? MINIMC_TEMP_STATUS_OPEN_CIRCUIT : MINIMC_TEMP_STATUS_SHORT_CIRCUIT;
        report->heater_duty_percent = 0U;
        return true;
    }

    const int16_t temp_ddC = ntc_adc_to_deci_c(raw_adc);
    if (temp_ddC > 3000)
    {
        thermistor_safety_lock();
    }
    report->current_temp_deci_c = temp_ddC;
    report->target_temp_deci_c = thermistor_get_target_deci_c();
    report->raw_adc_value = raw_adc;
    report->sensor_status = MINIMC_TEMP_STATUS_OK;
    report->heater_duty_percent = (uint8_t)((soft_pwm[0] > 0) ? soft_pwm[0] : 0);
    return true;
}
