static char cmdbuffer[BUFSIZE][MAX_CMD_SIZE];
static int bufindr = 0;
static int bufindw = 0;
static int buflen = 0;
static char urgent_order[8][16];
static int urgent_order_store = 0;
static int urgent_order_read = 0;
static int urgent_order_length = 0;

/**
 * @brief 将常规 G-code 指令压入 mycontrol 环形队列。
 */
void enquecommand(const char *cmd)
{
	if (buflen < BUFSIZE)
	{
		strcpy(&(cmdbuffer[bufindw][0]), cmd);
		bufindw = (bufindw + 1) % BUFSIZE;
		buflen += 1;
	}
}

/**
 * @brief 将紧急指令存入 mycontrol 优先队列。
 */
void store_instancy_cmd(char *cmd)
{
	if (urgent_order_length < 8)
	{
		strcpy(&(urgent_order[urgent_order_store][0]), cmd);
		urgent_order_store = (urgent_order_store + 1) % 8;
		urgent_order_length++;
	}
}

/**
 * @brief 从紧急队列取出一项插队到常规指令队列。
 */
char read_instancy_cmd(void)
{
	if ((urgent_order_length < 1) || (buflen >= (BUFSIZE - 1)))
	{
		return 0;
	}
	urgent_order_length--;
	enquecommand(&(urgent_order[urgent_order_read][0]));
	urgent_order_read = (urgent_order_read + 1) % 8;
	return 1;
}

/**
 * @brief 清空 mycontrol 紧急指令队列。
 */
void clear_instancy_cmd(void)
{
	urgent_order_length = 0;
	urgent_order_read = 0;
	urgent_order_store = 0;
}

/**
 * @brief 清空 mycontrol 常规指令队列。
 */
void clear_command_queue(void)
{
	bufindr = 0;
	bufindw = 0;
	buflen = 0;
}

/**
 * @brief 宿主单测模式执行 mycontrol 队列当前 G/M/T 指令。
 */
void process_commands(void)
{
	const char *cmd = cmdbuffer[bufindr];
	if ((strncmp(cmd, "M104", 4) == 0) || (strncmp(cmd, "M109", 4) == 0))
	{
		const char *s_ptr = strchr(cmd, 'S');
		if (s_ptr != NULL)
		{
			float temp = (float)atof(s_ptr + 1);
			if (temp < 0.0f)
			{
				temp = 0.0f;
			}
			if (temp > 300.0f)
			{
				temp = 300.0f;
			}
			thermistor_set_target_deci_c((int16_t)(temp * 10.0f));
		}
	}
	else if ((cmd[0] == 'T') && (cmd[1] >= '0') && (cmd[1] <= '3'))
	{
		const uint8_t slot = (uint8_t)(cmd[1] - '0');
		const uint8_t mask = (Board_getFilamentStatus() == 0U) ? 0x0FU : 0x00U;
		load_filament_Flag = 0;
		th_debug_notify_filament("SELECT", slot, mask, "DONE");
	}
	else if (strncmp(cmd, "M112", 4) == 0)
	{
		quickStop();
		thermistor_set_target_deci_c(0);
	}
}
