static char s_th_last_gcode[MAX_CMD_SIZE] = {0};
static uint32_t s_th_enqueued_count = 0U;

/**
 * @brief 重置 TH 控制队列状态。
 */
void th_control_reset_queue(void)
{
	clear_instancy_cmd();
	clear_command_queue();
	s_th_last_gcode[0] = '\0';
	s_th_enqueued_count = 0U;
}

/**
 * @brief 将二进制协议转换的 G-code 压入 TH 控制环形队列（0x10/0x15/0x17/0x19/0x1B/0x1C）。
 */
bool th_control_enqueue_gcode(const char *line, uint8_t len, bool is_instant)
{
	if ((line == NULL) || (len == 0U) || (len >= (uint8_t)MAX_CMD_SIZE))
	{
		return false;
	}
	char safe_cmd[MAX_CMD_SIZE];
	memcpy(safe_cmd, line, len);
	safe_cmd[len] = '\0';
	memcpy(s_th_last_gcode, safe_cmd, (size_t)len + 1U);
	s_th_enqueued_count++;

	if (is_instant && (urgent_order_length < 8) && (len < 15U))
	{
		store_instancy_cmd(safe_cmd);
		return true;
	}
	if (buflen >= BUFSIZE)
	{
		return false;
	}
	enquecommand(safe_cmd);
	return true;
}

/**
 * @brief 非阻塞单步推进 TH 控制队列中的紧急指令与常规 G-code。
 */
void th_control_poll_once(void)
{
	(void)read_instancy_cmd();
	if (buflen > 0)
	{
		process_commands();
		buflen--;
		bufindr = (bufindr + 1) % BUFSIZE;
	}
	USART3_forward_service();
}

