  const uint8_t flags = frame[4];
  const bool valid_dst = ((dst_id == MINIMC_NODE_TH) || (dst_id == MINIMC_NODE_BROADCAST));
  if (((flags & MINIMC_FLAG_PROTO_V2) == 0U) || ((flags & MINIMC_FLAG_IS_RESPONSE) != 0U) || (!valid_dst))
  {
