/**
 * @brief 将 TH 耗材动作同步至控制队列并更新运行时标志。
 */
static const char *apply_th_filament_action(uint8_t cmd_id, uint8_t slot_id, uint8_t action, int16_t len_mm)
{
    char gcode[24];
    const int tn = snprintf(gcode, sizeof(gcode), "T%u", (unsigned int)slot_id);
    if (tn > 0)
    {
        (void)th_control_enqueue_gcode(gcode, (uint8_t)tn, false);
    }
    if ((cmd_id == MINIMC_CMD_SLOT_SELECT) && (action == 0U))
    {
        load_filament_Flag = 0;
        return "SELECT";
    }
    const int16_t dist = (len_mm > 0) ? len_mm : 10;
    if (action == 2U)
    {
        load_filament_Flag = 2;
        const int en = snprintf(gcode, sizeof(gcode), "G1 E-%d F300", (int)dist);
        if (en > 0)
        {
            (void)th_control_enqueue_gcode(gcode, (uint8_t)en, false);
        }
        return "UNLOAD";
    }
    load_filament_Flag = 1;
    const int en = snprintf(gcode, sizeof(gcode), "G1 E%d F300", (int)dist);
    if (en > 0)
    {
        (void)th_control_enqueue_gcode(gcode, (uint8_t)en, false);
    }
    return "LOAD";
}

/**
 * @brief 处理 0x15/0x19/0x1B 耗材与选槽指令并返回 0x19 真实状态帧。
 */
static uint16_t handle_th_filament_cmd(const uint8_t *frame, uint16_t plen, uint8_t *out_buf)
{
    const uint8_t src_id = frame[2];
    const uint8_t cmd_id = frame[5];
    const uint16_t seq = (uint16_t)frame[8] | ((uint16_t)frame[9] << 8U);
    if (plen < (uint16_t)sizeof(minimc_filament_req_t))
    {
        return build_nack_resp(src_id, seq, 0x02U, out_buf);
    }
    const uint8_t slot_id = frame[12];
    const uint8_t action = frame[13];
    const int16_t len_mm = (int16_t)((uint16_t)frame[14] | ((uint16_t)frame[15] << 8U));
    if ((slot_id >= 4U) || (action > 3U))
    {
        return build_nack_resp(src_id, seq, 0x03U, out_buf);
    }
    const char *op_str = apply_th_filament_action(cmd_id, slot_id, action, len_mm);
    const uint8_t present_mask = (Board_getFilamentStatus() == 0U) ? 0x0FU : 0x00U;
    th_debug_notify_filament(op_str, slot_id, present_mask, "DONE");

    {
        return handle_th_filament_cmd(frame, plen, out_buf);
    }
    if (cmd_id == MINIMC_CMD_MOTION_STOP)
    {
        return handle_th_motion_stop(frame, plen, out_buf);
    }
    if (cmd_id == MINIMC_CMD_GCODE_EXEC)
    {
        return handle_th_gcode_exec(frame, plen, out_buf);
    }
    return build_nack_resp(src_id, seq, 0x04U, out_buf);
}

/**
 * @brief 校验接收帧目标节点与请求标志后执行分发并回发响应。
 */
static void minimc_proto_handle_frame(const uint8_t *frame, uint16_t len)
{
    if ((frame == NULL) || (len < MINIMC_HEADER_SIZE))
    {
        return;
    }
    const uint8_t dst_id = frame[3];
    const uint8_t flags = frame[4];
    if (((dst_id != MINIMC_NODE_TH) && (dst_id != MINIMC_NODE_BROADCAST)) ||
        ((flags & MINIMC_FLAG_IS_RESPONSE) != 0U))
    {
        return;
    }
    const uint16_t plen = (uint16_t)frame[10] | ((uint16_t)frame[11] << 8U);
    static uint8_t s_resp_buf[MINIMC_MAX_FRAME_SIZE];
    const uint16_t resp_len = dispatch_th_command(frame, plen, s_resp_buf);
    if (resp_len > 0U)
    {
        usart1_send_raw(s_resp_buf, resp_len);
    }
}

static void parser_step_sof(uint8_t byte)
{
    if (s_parser_state == PARSER_STATE_IDLE)
    {
        if (byte == MINIMC_SOF_1)
        {
            s_rx_frame[0] = MINIMC_SOF_1;
            s_rx_index = 1U;
            s_parser_state = PARSER_STATE_SOF2;
        }
        else
        {
            usart1_push_text_byte(byte);
        }
    }
    else if (s_parser_state == PARSER_STATE_SOF2)
    {
        if (byte == MINIMC_SOF_2)
        {
            s_rx_frame[1] = MINIMC_SOF_2;
            s_rx_index = 2U;
            s_parser_state = PARSER_STATE_HEADER;
        }
        else if (byte == MINIMC_SOF_1)
        {
            usart1_push_text_byte(MINIMC_SOF_1);
            s_rx_frame[0] = MINIMC_SOF_1;
            s_rx_index = 1U;
        }
        else
        {
            usart1_push_text_byte(MINIMC_SOF_1);
            usart1_push_text_byte(byte);
            s_parser_state = PARSER_STATE_IDLE;
            s_rx_index = 0U;
        }
    }
}

static void parser_step_body(uint8_t byte)
{
    s_rx_frame[s_rx_index] = byte;
    s_rx_index++;

    if (s_parser_state == PARSER_STATE_HEADER)
    {
        if (s_rx_index == MINIMC_HEADER_SIZE)
        {
            const uint16_t plen = (uint16_t)s_rx_frame[10] | ((uint16_t)s_rx_frame[11] << 8U);
            if (plen > MINIMC_MAX_PAYLOAD_SIZE)
            {
                s_parser_state = PARSER_STATE_IDLE;
                s_rx_index = 0U;
                return;
            }
            s_expected_len = MINIMC_HEADER_SIZE + plen + MINIMC_CRC_SIZE;
            s_parser_state = (plen == 0U) ? PARSER_STATE_CRC : PARSER_STATE_PAYLOAD;
        }
    }
    else if (s_parser_state == PARSER_STATE_PAYLOAD)
    {
        if (s_rx_index == (s_expected_len - MINIMC_CRC_SIZE))
        {
            s_parser_state = PARSER_STATE_CRC;
        }
    }
    else if (s_parser_state == PARSER_STATE_CRC)
    {
        if (s_rx_index >= s_expected_len)
        {
            const uint16_t calc_crc = minimc_crc16(s_rx_frame, s_expected_len - MINIMC_CRC_SIZE);
            const uint16_t rx_crc = (uint16_t)s_rx_frame[s_expected_len - 2U] |
                                    ((uint16_t)s_rx_frame[s_expected_len - 1U] << 8U);
            if (calc_crc == rx_crc)
            {
                minimc_proto_handle_frame(s_rx_frame, s_expected_len);
            }
            s_parser_state = PARSER_STATE_IDLE;
            s_rx_index = 0U;
        }
    }
}

