//  G91 - Use Relative Coordinates
//  G92 - Set current position to cordinates given

// RepRap M Codes
//  M0   - Unconditional stop - Wait for user to press a button on the LCD (Only if ULTRA_LCD is enabled)
//  M1   - Same as M0
//  M104 - Set extruder target temp
//  M105 - Read current temp
//  M106 - Fan on
//  M107 - Fan off
//  M109 - Wait for extruder current temp to reach target temp.
//  M114 - Display current position

// Custome M Codes
//  M15  - update flash data (font data ; icon data and so on)
//  M16  - screen_adjust
//  M17  - Enable/Power all stepper motors
//  M18  - Disable all stepper motors; same as M84
//  M20  - List SD card
//  M21  - Init SD card
/**
 * @brief 弱符号默认实现：紧急停止步进电机队列。
 */
__attribute__((weak)) void quickStop(void)
{
}

/**
 * @brief 弱符号默认实现：向 TH 控制环形队列压入一条 G-code 指令。
 */
__attribute__((weak)) bool th_control_enqueue_gcode(const char *line, uint8_t len, bool is_instant)
{
    if ((line == NULL) || (len == 0U) || (len >= sizeof(s_weak_last_gcode)))
    {
        return false;
    }
    if ((!is_instant) && (s_weak_count >= TH_WEAK_CMD_BUFSIZE))
    {
        return false;
    }
    memcpy(s_weak_last_gcode, line, len);
    s_weak_last_gcode[len] = '\0';
    memcpy(s_weak_cmd_ring[s_weak_head], s_weak_last_gcode, (size_t)len + 1U);
    s_weak_head = (uint8_t)((s_weak_head + 1U) % TH_WEAK_CMD_BUFSIZE);
    if (s_weak_count < TH_WEAK_CMD_BUFSIZE)
    {
        s_weak_count++;
    }
    s_weak_enqueued_count++;
    return true;
}

/**
 * @brief 弱符号默认实现：单步弹出并执行 TH 控制环形队列中的一条 G-code。
 */
__attribute__((weak)) void th_control_poll_once(void)
{
    if (s_weak_count == 0U)
    {
        return;
    }
    const char *cmd = s_weak_cmd_ring[s_weak_tail];
    s_weak_tail = (uint8_t)((s_weak_tail + 1U) % TH_WEAK_CMD_BUFSIZE);
    s_weak_count--;
    th_apply_gcode_side_effects(cmd);
}

/**
 * @brief 弱符号默认实现：查询 TH 控制环形队列剩余槽位。
 */
__attribute__((weak)) uint8_t th_control_get_queue_free(void)
{
    return (s_weak_count < TH_WEAK_CMD_BUFSIZE) ? (uint8_t)(TH_WEAK_CMD_BUFSIZE - s_weak_count) : 0U;
}

/**
 * @brief 弱符号默认实现：获取最近入队的 G-code 字符串。
 */
__attribute__((weak)) const char *th_control_get_last_gcode(void)
{
    return s_weak_last_gcode;
}

/**
 * @brief 弱符号默认实现：获取累计入队的 G-code 计数。
 */
__attribute__((weak)) uint32_t th_control_get_enqueued_count(void)
{
    return s_weak_enqueued_count;
}

/**
 * @brief 弱符号默认实现：重置 TH 控制队列状态。
 */
__attribute__((weak)) void th_control_reset_queue(void)
{
    {
