    out_buf[10] = 0x10U; /* 16 bytes */
    out_buf[11] = 0x00U;

    out_buf[12] = 0x02U; /* proto_ver = 2 (LE) */
    out_buf[13] = 0x00U;
    out_buf[14] = (uint8_t)FW_VERSION_MAJOR;
    out_buf[15] = (uint8_t)FW_VERSION_MINOR;

    out_buf[16] = (uint8_t)(TH_BOOT_ID & 0xFFU);
    out_buf[17] = (uint8_t)((TH_BOOT_ID >> 8U) & 0xFFU);
    out_buf[18] = (uint8_t)((TH_BOOT_ID >> 16U) & 0xFFU);
    out_buf[19] = (uint8_t)((TH_BOOT_ID >> 24U) & 0xFFU);

    out_buf[20] = (uint8_t)(TH_GIT_COMMIT & 0xFFU);
    out_buf[21] = (uint8_t)((TH_GIT_COMMIT >> 8U) & 0xFFU);
    out_buf[22] = (uint8_t)((TH_GIT_COMMIT >> 16U) & 0xFFU);
    out_buf[23] = (uint8_t)((TH_GIT_COMMIT >> 24U) & 0xFFU);

    out_buf[24] = (uint8_t)(TH_CAPABILITY_FLAGS & 0xFFU);
    out_buf[25] = (uint8_t)((TH_CAPABILITY_FLAGS >> 8U) & 0xFFU);
    out_buf[26] = (uint8_t)((TH_CAPABILITY_FLAGS >> 16U) & 0xFFU);
    out_buf[27] = (uint8_t)((TH_CAPABILITY_FLAGS >> 24U) & 0xFFU);

    const uint16_t crc = minimc_crc16(out_buf, 28U);
    out_buf[28] = (uint8_t)(crc & 0xFFU);
    out_buf[29] = (uint8_t)((crc >> 8U) & 0xFFU);
    return 30U;
}

static uint16_t build_pong_resp(uint8_t dst_id, uint16_t seq, const uint8_t *payload, uint8_t *out_buf)
{
    if (out_buf == NULL)
    {
        return 0U;
    }
    out_buf[0] = MINIMC_SOF_1;
    out_buf[1] = MINIMC_SOF_2;
    out_buf[2] = MINIMC_NODE_TH;
    out_buf[3] = dst_id;
    out_buf[4] = (uint8_t)(MINIMC_FLAG_IS_RESPONSE | MINIMC_FLAG_PROTO_V2);
    out_buf[5] = MINIMC_CMD_PONG;
    out_buf[6] = MINIMC_DEFAULT_HOP_LIMIT;
    out_buf[7] = MINIMC_DEFAULT_ROUTE;
    out_buf[8] = (uint8_t)(seq & 0xFFU);
    out_buf[9] = (uint8_t)((seq >> 8U) & 0xFFU);
    out_buf[10] = 0x0CU; /* 12 bytes */
    out_buf[11] = 0x00U;

    out_buf[12] = (payload != NULL) ? payload[0] : 0x00U;
    out_buf[13] = (payload != NULL) ? payload[1] : 0x00U;
    out_buf[14] = (payload != NULL) ? payload[2] : 0x00U;
    out_buf[15] = (payload != NULL) ? payload[3] : 0x00U;

